#!/usr/bin/env python3
"""Decode embedded account_login.py into the chatbot root."""
from __future__ import annotations
import base64, os, zlib
from pathlib import Path
ROOT = Path(os.environ.get("AGY_CHAT_ROOT", str(Path.home() / "services" / "chatbot")))
BLOB = """"""
def main():
    data = zlib.decompress(base64.b64decode(BLOB))
    path = ROOT / "account_login.py"
    path.write_bytes(data)
    print(f"wrote {path} ({len(data)} bytes)")
if __name__ == "__main__":
    main()
